SELECT
,
d.dept_name AS deptName,
m.major_name AS majorName,
c.class_name AS className,
c.grade AS grade
FROM stu_student s
LEFT JOIN base_dept d ON d.id = s.dept_id
LEFT JOIN base_major m ON m.id = s.major_id
LEFT JOIN base_class c ON c.id = s.class_id
WHERE s.deleted = 0



            AND s.id = #{scope.studentId}


            AND s.class_id IN
            #{cid}


            AND 1 = 0




    AND (s.student_no LIKE CONCAT('%', #{q.keyword}, '%')
    OR s.name LIKE CONCAT('%', #{q.keyword}, '%')
    OR s.phone LIKE CONCAT('%', #{q.keyword}, '%'))

AND s.dept_id = #{q.deptId}
AND s.major_id = #{q.majorId}
AND s.class_id = #{q.classId}
AND c.grade = #{q.grade}
AND s.gender = #{q.gender}
AND s.status = #{q.status}
ORDER BY s.class_id ASC, s.student_no ASC
